.libPaths(c('work/Rlib',.libPaths()));library(mice)
out<-'outputs/final_analysis';r<-read.csv('outputs/cox_results.csv');mi<-read.csv(file.path(out,'multiple_imputation_cox.csv'));ex<-read.csv(file.path(out,'external_cox.csv'))
primary<-r[r$analysis%in%c('mortstat_M3','cvd_death_M3','cancer_death_M3'),c('event','HR','lower','upper')];names(primary)[1]<-'outcome';primary$analysis<-'Primary complete cases';mi<-mi[,c('outcome','HR','lower','upper')];mi$analysis<-'Multiple imputation';ex<-ex[ex$model=='M3',c('outcome','HR','lower','upper')];ex$analysis<-'Historical validation';z<-rbind(primary,mi,ex);z$label<-paste(z$analysis,z$outcome,sep=': ')
png(file.path(out,'cohort_results_forest.png'),width=1800,height=1200,res=180);par(mar=c(5,16,3,2));yy<-rev(seq_len(nrow(z)));plot(z$HR,yy,log='x',xlim=c(.8,2),yaxt='n',pch=19,col=rep(c('#335e77','#a34b50','#8c793f'),each=3),xlab='Mortality hazard ratio per fixed development SD',ylab='',main='Primary, imputed, and validation analyses');segments(z$lower,yy,z$upper,yy,lwd=2);axis(2,at=yy,labels=z$label,las=1,cex.axis=.85);abline(v=1,lty=2,col='gray50');dev.off()
m<-read.csv(file.path(out,'multivariable_mr.csv'));png(file.path(out,'multivariable_mr_forest.png'),width=1600,height=1000,res=180);par(mar=c(5,10,3,2));yy<-rev(seq_len(nrow(m)));plot(m$OR,yy,xlim=range(c(m$lower,m$upper)),log='x',pch=19,yaxt='n',ylab='',xlab='Outcome odds ratio per GWAS exposure unit',main='Multivariable MR adjusted for the other two lipids');segments(m$lower,yy,m$upper,yy,lwd=2);axis(2,at=yy,labels=paste(m$exposure,'to',m$outcome),las=1);abline(v=1,lty=2);dev.off()
cams<-list();for(s in c('GSE98895_MetS','GSE9006_T1D','GSE9006_T2D')){x<-read.csv(file.path(out,paste0(s,'_hallmark_camera.csv')));x<-head(x[order(x$FDR),],6);x$comparison<-s;cams[[s]]<-x};ca<-do.call(rbind,cams);write.csv(ca,file.path(out,'hallmark_top_sets.csv'),row.names=FALSE)
png(file.path(out,'hallmark_comparison.png'),width=1900,height=1400,res=170);par(mfrow=c(3,1),mar=c(4,22,2,2));for(s in names(cams)){x<-cams[[s]];x<-x[nrow(x):1,];barplot(-log10(x$FDR),names.arg=gsub('HALLMARK_','',x$pathway),horiz=TRUE,las=1,col=ifelse(x$Direction=='Up','#b45b5f','#46768e'),main=s,xlab='-log10 camera FDR',cex.names=.75);abline(v=-log10(.05),lty=2)};dev.off()
png(file.path(out,'study_flow.png'),width=1500,height=1300,res=170);par(mar=c(0,0,2,0));plot.new();plot.window(xlim=c(0,1),ylim=c(0,1));labels<-c('NHANES 2005-2010 and 2015-2018\n11,529 adults with positive fasting weights','Exclude pregnancy: 236\n11,293 nonpregnant fasting adults','Complete score, eligible linkage, positive examination follow-up\n10,868 participants; 357 CVD deaths','Primary complete-covariate analysis\n9,794 participants; 312 CVD deaths','Multiple imputation of covariates\n10,868 participants; 30 imputed datasets');ys<-seq(.87,.15,length.out=5);for(i in 1:5){rect(.1,ys[i]-.055,.9,ys[i]+.055,col='#f0f3f5',border='#758997');text(.5,ys[i],labels[i],cex=.9);if(i<5)arrows(.5,ys[i]-.06,.5,ys[i+1]+.06,length=.08)};title('Development cohort and analysis samples');dev.off()
